parameters.jsCode:
const store=$getWorkflowStaticData('global');

if (!store.users) store.users={};
if (!store.jobs) store.jobs=[];

const m=$json.message ?? {};
const text=(m.text ?? '').trim();

const chatId=m.chat?.id;
const telegramId=String(m.from?.id ?? '');

if (!chatId || !telegramId) {
  return [];
}

if (!store.users[telegramId]) {
  store.users[telegramId]={
    telegram_id:telegramId,
    chat_id:chatId,
    username:m.from?.username ?? '',
    first_name:m.from?.first_name ?? '',
    language:'ar-SA',
    voice:'ar-SA-HamedNeural',
    video_aspect:'9:16',

    awaiting:null,

    pending_title:null,
    pending_topic:null,
    pending_duration_seconds:null,
    pending_duration_label:null,
    pending_style:null,
    pending_material_source_mode:'auto',
    pending_materials:[],
    pending_flow_scene_id:null,
    pending_flow_materials:[],

    created_at:new Date().toISOString()
  };
}

const user=store.users[telegramId];

if (!Array.isArray(user.pending_materials)) {
  user.pending_materials=[];
}

if (!Array.isArray(user.pending_flow_materials)) {
  user.pending_flow_materials=[];
}

if (
  user.pending_flow_scene_id === undefined
) {
  user.pending_flow_scene_id=null;
}

if (
  user.pending_duration_seconds === undefined
) {
  user.pending_duration_seconds=null;
}

if (
  user.pending_duration_label === undefined
) {
  user.pending_duration_label=null;
}

if (
  user.pending_material_source_mode === undefined
) {
  user.pending_material_source_mode='auto';
}

user.chat_id=chatId;
user.username=m.from?.username ?? user.username ?? '';
user.first_name=m.from?.first_name ?? user.first_name ?? '';
user.last_seen_at=new Date().toISOString();


// ========================================================
// MATERIAL DETECTION
// ========================================================

const photos=
  Array.isArray(m.photo)
    ? m.photo
    : [];

let incomingMaterial=null;

if (photos.length) {

  const photo=
    photos[photos.length-1];

  incomingMaterial={
    type:'image',
    file_id:photo.file_id,
    extension:'jpg',
    mime_type:'image/jpeg'
  };

} else if (m.video?.file_id) {

  const name=String(
    m.video.file_name || ''
  );

  const ext=
    name.includes('.')
      ? name.split('.').pop().toLowerCase()
      : 'mp4';

  incomingMaterial={
    type:'video',
    file_id:m.video.file_id,
    extension:ext || 'mp4',
    mime_type:m.video.mime_type || 'video/mp4'
  };

} else if (m.document?.file_id) {

  const mime=String(
    m.document.mime_type || ''
  ).toLowerCase();

  if (
    mime.startsWith('image/') ||
    mime.startsWith('video/')
  ) {

    const name=String(
      m.document.file_name || ''
    );

    let ext=
      name.includes('.')
        ? name.split('.').pop().toLowerCase()
        : '';

    if (!ext) {
      const extensionMap={
        'image/jpeg':'jpg',
        'image/png':'png',
        'video/mp4':'mp4',
        'video/quicktime':'mov'
      };

      ext=
        extensionMap[mime]
        || 'mp4';
    }

    incomingMaterial={
      type:
        mime.startsWith('image/')
          ? 'image'
          : 'video',

      file_id:m.document.file_id,
      extension:ext,
      mime_type:mime
    };
  }
}


// ========================================================
// VISUAL STYLES
// ========================================================

const STYLE_OPTIONS={
  '1':{
    key:'realistic',
    label:'واقعي'
  },
  '2':{
    key:'cartoon',
    label:'كرتوني'
  },
  '3':{
    key:'illustration',
    label:'رسومي / Motion Graphics'
  },
  '4':{
    key:'3d',
    label:'ثلاثي الأبعاد 3D'
  },
  '5':{
    key:'futuristic',
    label:'تقني / مستقبلي'
  },
  '6':{
    key:'auto',
    label:'تلقائي'
  }
};

function resolveStyle(value) {
  const raw=String(value || '')
    .trim()
    .toLowerCase();

  if (STYLE_OPTIONS[raw]) {
    return STYLE_OPTIONS[raw];
  }

  const aliases={
    'واقعي':'1',
    'realistic':'1',

    'كرتوني':'2',
    'كرتون':'2',
    'cartoon':'2',

    'رسومي':'3',
    'رسوم':'3',
    'illustration':'3',
    'motion graphics':'3',

    '3d':'4',
    'ثلاثي الأبعاد':'4',
    'ثلاثي الابعاد':'4',

    'تقني':'5',
    'مستقبلي':'5',
    'futuristic':'5',

    'تلقائي':'6',
    'auto':'6'
  };

  const id=aliases[raw];

  return id
    ? STYLE_OPTIONS[id]
    : null;
}

function styleMenu(prefix='') {
  return `${prefix}🎨 اختر نمط المشاهد:

1️⃣ واقعي
2️⃣ كرتوني
3️⃣ رسومي / Motion Graphics
4️⃣ ثلاثي الأبعاد 3D
5️⃣ تقني / مستقبلي
6️⃣ تلقائي

أرسل الرقم من 1 إلى 6.`;
}


// ========================================================
// VIDEO DURATION
// ========================================================

const DURATION_OPTIONS={
  '1':{
    seconds:30,
    label:'30 ثانية'
  },
  '2':{
    seconds:45,
    label:'45 ثانية'
  },
  '3':{
    seconds:60,
    label:'60 ثانية'
  },
  '4':{
    seconds:90,
    label:'90 ثانية'
  },
  '5':{
    seconds:120,
    label:'دقيقتان'
  },
  '7':{
    seconds:0,
    label:'تلقائي'
  }
};

function resolveDuration(value) {
  const raw=String(value || '')
    .trim()
    .toLowerCase();

  if (DURATION_OPTIONS[raw]) {
    return DURATION_OPTIONS[raw];
  }

  const aliases={
    '30':'1',
    '30 ثانية':'1',

    '45':'2',
    '45 ثانية':'2',

    '60':'3',
    'دقيقة':'3',
    '1 دقيقة':'3',

    '90':'4',
    '90 ثانية':'4',

    '120':'5',
    'دقيقتان':'5',
    '2 دقيقة':'5',

    'تلقائي':'7',
    'auto':'7'
  };

  const id=aliases[raw];

  return id
    ? DURATION_OPTIONS[id]
    : null;
}

function durationMenu(prefix='') {
  return `${prefix}⏱ اختر مدة الفيديو:

1️⃣ 30 ثانية
2️⃣ 45 ثانية
3️⃣ 60 ثانية
4️⃣ 90 ثانية
5️⃣ دقيقتان
6️⃣ مدة مخصصة
7️⃣ تلقائي حسب المحتوى

أرسل الرقم من 1 إلى 7.`;
}

function parseCustomDuration(value) {
  const raw=String(value || '')
    .replace(/[^\d]/g,'');

  const seconds=Number(raw);

  if (
    !Number.isInteger(seconds) ||
    seconds < 15 ||
    seconds > 300
  ) {
    return null;
  }

  return seconds;
}

function estimateScriptSeconds(script) {
  const words=String(script || '')
    .trim()
    .split(/\s+/)
    .filter(Boolean)
    .length;

  if (!words) {
    return 0;
  }

  // Conservative estimate for Arabic narration.
  return Math.max(
    1,
    Math.round(words / 2.15)
  );
}


// ========================================================
// MATERIAL SOURCE MODE
// ========================================================

const MATERIAL_SOURCE_OPTIONS={
  '1':{
    key:'auto',
    label:'تلقائي Hybrid'
  },
  '2':{
    key:'user_pexels',
    label:'موادي + Pexels'
  },
  '3':{
    key:'flow_user_pexels',
    label:'Flow + موادي + Pexels'
  },
  '4':{
    key:'pexels_only',
    label:'Pexels فقط'
  }
};

function resolveMaterialSourceMode(value) {
  const raw=String(value || '')
    .trim()
    .toLowerCase();

  if (MATERIAL_SOURCE_OPTIONS[raw]) {
    return MATERIAL_SOURCE_OPTIONS[raw];
  }

  const aliases={
    'auto':'1',
    'hybrid':'1',
    'تلقائي':'1',
    'تلقائي hybrid':'1',
    'user_pexels':'2',
    'موادي + pexels':'2',
    'flow_user_pexels':'3',
    'pexels_only':'4',
    'pexels':'4'
  };

  const id=aliases[raw];

  return id
    ? MATERIAL_SOURCE_OPTIONS[id]
    : null;
}

function materialSourceMenu(prefix='') {
  return `${prefix}🎞 اختر مصادر المشاهد:

1️⃣ تلقائي Hybrid
2️⃣ موادي + Pexels
3️⃣ Flow + موادي + Pexels
4️⃣ Pexels فقط

أرسل الرقم من 1 إلى 4.`;
}


// ========================================================
// PINGOO_NOTEBOOKLM_HANDOFF_V1
// ========================================================

const NOTEBOOK_FIELDS=[
  'TITLE',
  'TOPIC',
  'DURATION',
  'STYLE',
  'SCRIPT',
  'VISUAL_NOTES',
  'SOURCES'
];

function parseNotebookPackage(value) {
  const sections={};
  let current=null;
  let currentLines=[];

  function flush() {
    if (current) {
      sections[current]=
        currentLines.join('\n').trim();
    }
  }

  const lines=String(value || '')
    .replace(/\r\n/g,'\n')
    .replace(/\r/g,'\n')
    .split('\n');

  for (const line of lines) {
    const match=line.match(
      /^\s*(TITLE|TOPIC|DURATION|STYLE|SCRIPT|VISUAL_NOTES|SOURCES)\s*:\s*(.*)$/i
    );

    if (match) {
      flush();
      current=match[1].toUpperCase();
      currentLines=[];

      if (match[2]) {
        currentLines.push(match[2]);
      }

      continue;
    }

    if (current) {
      currentLines.push(line);
    }
  }

  flush();
  return sections;
}

function notebookSourceCount(value) {
  return String(value || '')
    .split(/\n+/)
    .map(x => x.trim())
    .filter(Boolean)
    .length;
}


// ========================================================
// COMMON OUTPUT
// ========================================================

let command='';

if (text.startsWith('/')) {
  command=text
    .split(/\s+/)[0]
    .split('@')[0]
    .toLowerCase();
}

let route='reply';
let reply='';

let videoTitle='';
let videoSubject='';
let videoScript='';
let scriptMode='';

let visualStyle='auto';
let visualStyleLabel='تلقائي';

let targetDurationSeconds=0;
let targetDurationLabel='تلقائي';

let taskId='';

let materialFileId='';
let materialExtension='';
let materialMimeType='';

let supplementalMaterials=[];
let flowMaterials=[];

let materialSourceMode='auto';
let materialSourceModeLabel='تلقائي Hybrid';

let contentVisualNotes='';
let contentSources='';
let contentSourcesCount=0;


// ========================================================
// MATERIALS
// ========================================================

if (
  command === '/clean_cache' ||
  text === '🧹 تنظيف الكاش'
) {

  route='cache_cleanup';
  reply='';

} else if (command === '/drive_materials') {

  route='drive_import';
  reply='☁️ جاري فحص Google Drive...';

} else if (command === '/flow') {

  user.awaiting='flow_scene_id';
  user.pending_flow_scene_id=null;

  reply=
`🎨 Google Flow Materials

أرسل رقم المشهد الذي تريد إضافة مادة Flow له.

مثال:
3`;

} else if (
  !command &&
  user.awaiting === 'flow_scene_id' &&
  text
) {

  const sceneId=
    Number(
      String(text || '').trim()
    );

  if (
    !Number.isInteger(sceneId) ||
    sceneId < 1
  ) {

    reply=
`❌ رقم المشهد غير صحيح.

أرسل رقمًا صحيحًا أكبر من أو يساوي 1.`;

  } else {

    user.pending_flow_scene_id=sceneId;
    user.awaiting='flow_material';

    reply=
`✅ المشهد رقم ${sceneId}

الآن أرسل صورة أو فيديو تم إنتاجه في Google Flow.`;
  }

} else if (command === '/materials') {

  user.awaiting='materials';
  user.pending_materials=[];

  reply=
`📎 إضافة مواد

أرسل الصور أو الفيديوهات التي تريد استخدامها.

يمكنك إرسال عدة ملفات، واحدًا بعد الآخر.

عند الانتهاء أرسل:
/done`;

} else if (
  !command &&
  incomingMaterial &&
  user.awaiting === 'flow_material' &&
  Number(user.pending_flow_scene_id || 0) >= 1
) {

  route='flow_material_upload';

  materialFileId=
    incomingMaterial.file_id;

  materialExtension=
    incomingMaterial.extension;

  materialMimeType=
    incomingMaterial.mime_type;

  reply='';

} else if (
  !command &&
  incomingMaterial
) {

  route='material_upload';

  materialFileId=
    incomingMaterial.file_id;

  materialExtension=
    incomingMaterial.extension;

  materialMimeType=
    incomingMaterial.mime_type;

  reply='';

} else if (
  command === '/done' &&
  (
    user.awaiting === 'materials' ||
    user.awaiting === 'flow_material' ||
    user.awaiting === 'flow_scene_id' ||
    user.awaiting === 'flow_material_done'
  )
) {

  user.awaiting=null;
  user.pending_flow_scene_id=null;

  reply=
`✅ انتهت إضافة المواد.

📎 سيتم التحقق من الملفات الفعلية على السيرفر عند بدء الفيديو.

الآن استخدم:
/script
أو
/video
أو
/notebook`;

} else if (
  !command &&
  incomingMaterial
) {

  reply=
`📎 لإضافة صورة أو فيديو كمادة مساعدة استخدم أولًا:

/materials`;


// ========================================================
// START
// ========================================================

} else if (command === '/start') {

  user.awaiting=null;
  user.pending_title=null;
  user.pending_topic=null;
  user.pending_duration_seconds=null;
  user.pending_duration_label=null;
  user.pending_style=null;
  user.pending_material_source_mode='auto';
  user.pending_notebook_package=null;
  user.pending_flow_scene_id=null;
  user.pending_flow_materials=[];

  reply=
`🎬 Pingoo Video جاهز

/video إنشاء فيديو تلقائي
/script إدخال سكربت يدوي
/notebook بحث وإنتاج من NotebookLM
/flow إضافة مواد مولدة من Google Flow
/drive_materials استيراد مواد من Google Drive
/materials إضافة صور أو فيديوهات
/clean_cache تنظيف الكاش
/status حالة الطلب
/history السجل
/settings الإعدادات
/cancel إلغاء الطلب`;


// ========================================================
// /NOTEBOOK NOTEBOOKLM HANDOFF
// ========================================================

} else if (command === '/notebook') {

  user.awaiting='notebook_package';
  user.pending_title=null;
  user.pending_topic=null;
  user.pending_duration_seconds=null;
  user.pending_duration_label=null;
  user.pending_style=null;
  user.pending_notebook_package=null;

  reply=
`📚 وضع NotebookLM

جهّز المحتوى في NotebookLM ثم أرسل حزمة الإنتاج هنا.

الصيغة المطلوبة:

TITLE:
...

TOPIC:
...

DURATION:
60

STYLE:
futuristic

SCRIPT:
...

VISUAL_NOTES:
...

SOURCES:
...`;

} else if (
  !command &&
  user.awaiting === 'notebook_package' &&
  text
) {

  const pkg=
    parseNotebookPackage(text);

  const required=[
    'TITLE',
    'TOPIC',
    'SCRIPT'
  ];

  const missing=
    required.find(
      key => !String(pkg[key] || '').trim()
    );

  if (missing) {

    reply=
`❌ حزمة NotebookLM غير مكتملة.

الحقل الناقص:
${missing}

أرسل الحزمة كاملة من جديد.`;

  } else {

    const rawDuration=
      String(pkg.DURATION || 'auto')
        .trim();

    let parsedDuration=null;

    if (
      !rawDuration ||
      rawDuration.toLowerCase() === 'auto' ||
      rawDuration === 'تلقائي'
    ) {
      parsedDuration={
        seconds:0,
        label:'تلقائي'
      };
    } else {
      const seconds=
        parseCustomDuration(rawDuration);

      if (seconds) {
        parsedDuration={
          seconds,
          label:`${seconds} ثانية`
        };
      }
    }

    if (!parsedDuration) {

      reply=
`❌ مدة NotebookLM غير صحيحة.

المسموح:
15-300 ثانية أو auto.

أرسل الحزمة كاملة من جديد.`;

    } else {

      const selected=
        resolveStyle(pkg.STYLE || 'auto');

      if (!selected) {

        reply=
`❌ نمط NotebookLM غير صحيح.

المسموح:
realistic
cartoon
illustration
3d
futuristic
auto

أرسل الحزمة كاملة من جديد.`;

      } else {

        videoTitle=String(pkg.TITLE || '').trim();
        videoSubject=String(pkg.TOPIC || '').trim();
        videoScript=String(pkg.SCRIPT || '').trim();

        visualStyle=selected.key;
        visualStyleLabel=selected.label;

        targetDurationSeconds=parsedDuration.seconds;
        targetDurationLabel=parsedDuration.label;

        contentVisualNotes=
          String(pkg.VISUAL_NOTES || '').trim();

        contentSources=
          String(pkg.SOURCES || '').trim();

        contentSourcesCount=
          notebookSourceCount(contentSources);

        user.awaiting=null;
        user.pending_title=null;
        user.pending_topic=null;
        user.pending_duration_seconds=null;
        user.pending_duration_label=null;
        user.pending_style=null;
        user.pending_notebook_package={
          title:videoTitle,
          topic:videoSubject,
          script:videoScript,
          duration_seconds:targetDurationSeconds,
          duration:targetDurationLabel,
          style:visualStyle,
          style_label:visualStyleLabel,
          visual_notes:contentVisualNotes,
          sources:contentSources,
          sources_count:contentSourcesCount
        };
        user.pending_material_source_mode='auto';
        user.awaiting='notebook_material_source';

        reply=materialSourceMenu(
`✅ تم استلام حزمة NotebookLM.

🎬 العنوان:
${videoTitle}

📝 الموضوع:
${videoSubject}

⏱ المدة:
${targetDurationLabel}

🎨 النمط:
${visualStyleLabel}

📚 المصادر:
${contentSourcesCount}

`
        );
      }
    }
  }

} else if (
  !command &&
  user.awaiting === 'notebook_material_source' &&
  text
) {

  const selectedSource=
    resolveMaterialSourceMode(text);

  if (!selectedSource) {

    reply=materialSourceMenu(
`❌ اختيار مصادر المشاهد غير صحيح.

`
    );

  } else {

    const pkg=
      user.pending_notebook_package || {};

    videoTitle=String(pkg.title || '').trim();
    videoSubject=String(pkg.topic || '').trim();
    videoScript=String(pkg.script || '').trim();

    visualStyle=String(pkg.style || 'auto');
    visualStyleLabel=String(pkg.style_label || 'تلقائي');

    targetDurationSeconds=
      Number(pkg.duration_seconds || 0);

    targetDurationLabel=
      String(pkg.duration || 'تلقائي');

    contentVisualNotes=
      String(pkg.visual_notes || '');

    contentSources=
      String(pkg.sources || '');

    contentSourcesCount=
      Number(pkg.sources_count || 0);

    materialSourceMode=selectedSource.key;
    materialSourceModeLabel=selectedSource.label;
    user.pending_material_source_mode=materialSourceMode;

    user.awaiting=null;
    user.pending_title=null;
    user.pending_topic=null;
    user.pending_duration_seconds=null;
    user.pending_duration_label=null;
    user.pending_style=null;
    user.pending_notebook_package=null;

    route='video';
    scriptMode='notebook';

    reply=
`✅ تم اختيار مصادر المشاهد:
${materialSourceModeLabel}

جاري إنشاء الفيديو...`;
  }


// ========================================================
// /VIDEO AUTO
// ========================================================

} else if (command === '/video') {

  videoSubject=text
    .replace(/^\/video(?:@\w+)?/i,'')
    .trim();

  user.pending_title=null;
  user.pending_duration_seconds=null;
  user.pending_duration_label=null;
  user.pending_style=null;
  user.pending_material_source_mode='auto';

  if (!videoSubject) {

    user.awaiting='video_topic';
    user.pending_topic=null;

    reply=
`🎬 أرسل الآن موضوع الفيديو.

مثال:
فوائد النوم وتأثيره على الدماغ`;

  } else {

    user.pending_topic=videoSubject;
    user.awaiting='video_duration';

    reply=durationMenu(
`✅ تم حفظ الموضوع:
${videoSubject}

`
    );
  }


// ========================================================
// /SCRIPT MANUAL
// ========================================================

} else if (command === '/script') {

  user.pending_title=null;
  user.pending_topic=null;
  user.pending_duration_seconds=null;
  user.pending_duration_label=null;
  user.pending_style=null;
  user.pending_material_source_mode='auto';

  user.awaiting='manual_title';

  reply=
`✍️ وضع السكربت اليدوي

1️⃣ أرسل الآن عنوان الفيديو.`;

} else if (
  !command &&
  user.awaiting === 'manual_title' &&
  text
) {

  user.pending_title=text;
  user.awaiting='manual_topic';

  reply=
`✅ تم حفظ العنوان:
${text}

2️⃣ أرسل الآن موضوع الفيديو.`;

} else if (
  !command &&
  user.awaiting === 'manual_topic' &&
  text
) {

  user.pending_topic=text;
  user.awaiting='manual_duration';

  reply=durationMenu(
`✅ تم حفظ الموضوع:
${text}

3️⃣ `
  );


// ========================================================
// MANUAL DURATION
// ========================================================

} else if (
  !command &&
  user.awaiting === 'manual_duration' &&
  text
) {

  if (text.trim() === '6') {

    user.awaiting='manual_duration_custom';

    reply=
`⏱ أرسل المدة المطلوبة بالثواني.

الحد الأدنى: 15 ثانية
الحد الأعلى: 300 ثانية

مثال:
75`;

  } else {

    const duration=
      resolveDuration(text);

    if (!duration) {

      reply=durationMenu(
