function normalizeText(value) {
  return String(value || '')
    .replace(/\r\n/g,'\n')
    .replace(/\r/g,'\n')
    .replace(/[“”]/g,'"')
    .replace(/\s+/g,' ')
    .trim();
}

function parseRequirements(prompt) {
  const text=normalizeText(prompt);
  const lower=text.toLowerCase();
  const req={
    topic:text,
    language:/\b(ar|arabic)\b|العربية|عربي/.test(lower) ? 'ar' : ($json.video_language || 'ar-SA'),
    target_duration:Number($json.target_duration_seconds || 0),
    visual_style:String($json.visual_style || 'auto'),
    audience:'',
    platform:'',
    material_source_mode:String($json.material_source_mode || 'auto'),
    special_scene_instructions:[],
    subtitle_required:/ترجمة|subtitle|subtitles/i.test(text),
  };

  const durationMatch=text.match(/(\d{2,3})\s*(?:ثانية|ثواني|second|seconds|sec|s)\b/i);
  if (durationMatch) {
    const seconds=Number(durationMatch[1]);
    if (Number.isInteger(seconds) && seconds >= 15 && seconds <= 300) {
      req.target_duration=seconds;
    }
  }

  const quoted=text.match(/["']([^"']{4,120})["']/);
  const how=text.match(/(?:يشرح|عن|حول)[:\s]+([^\.\n،]+(?:\؟|\?)?)/i);
  if (quoted) {
    req.topic=quoted[1].trim();
  } else if (how) {
    req.topic=how[1].trim();
  }
  req.topic=req.topic
    .replace(/^كيف\s+/,'كيف ')
    .replace(/[.،]+$/,'')
    .trim();

  const audience=text.match(/الجمهور\s*[:：]\s*([^\.\n،]+)/i);
  if (audience) req.audience=audience[1].trim();

  if (/tiktok|تيك توك/i.test(text)) req.platform='TikTok';
  if (/reels|ريلز/i.test(text)) req.platform=req.platform ? `${req.platform}, Reels` : 'Reels';

  const style=text.match(/الأسلوب البصري\s*[:：]\s*([^\.\n]+)/i);
  if (style) {
    req.visual_style=style[1].trim();
  } else if (/تقني|مستقبلي|futuristic/i.test(text)) {
    req.visual_style='تقني مستقبلي واقعي';
  }

  if (/flow_user_pexels|google flow|flow|أنشئ لقطات Google Flow|لقطات Google Flow/i.test(text)) {
    req.material_source_mode='flow_user_pexels';
  } else if (/pexels فقط|pexels_only/i.test(text)) {
    req.material_source_mode='pexels_only';
  }

  const scenePatterns=[
    /ابدأ\s+ب([^\.\n]+)/ig,
    /ثم\s+اشرح\s+([^\.\n،]+)/ig,
    /ثم\s+([^\.\n،]+)/ig,
    /واختتم\s+ب([^\.\n]+)/ig,
  ];
  for (const pattern of scenePatterns) {
    const matches=text.matchAll(pattern);
    for (const match of matches) {
      const value=String(match[1] || '').trim();
      if (value && !req.special_scene_instructions.includes(value)) {
        req.special_scene_instructions.push(value);
      }
    }
  }

  return req;
}

