const files=
  Array.isArray(response?.data?.files)
    ? response.data.files
    : [];

const telegramId=
  String(
    ctx.telegram_id || ''
  );

const prefix=
  `tg-${telegramId}-`;


// ========================================================
// Find actual Telegram files saved by API.
// Filename format:
// tg-TELEGRAMID-TIMESTAMP.ext
// ========================================================

const candidates=[];

for (const entry of files) {

  const name=
    String(
      entry?.file
      || entry?.name
      || ''
    );

  if (
    !name.startsWith(prefix)
  ) {
    continue;
  }

  const rest=
    name.slice(
      prefix.length
    );

  const match=
    rest.match(
      /^(\d+)/
    );

  const timestamp=
    match
      ? Number(match[1])
      : 0;

  candidates.push({
    name,
    timestamp,
    size:Number(
      entry?.size || 0
    )
  });
}


// ========================================================
// Latest upload batch:
// Walk backwards while gaps are <= 30 minutes.
// This prevents yesterday/older batches being reused.
// ========================================================

candidates.sort(
  (a,b) =>
    a.timestamp-b.timestamp
);

let latestBatch=[];

if (candidates.length) {

  let i=
    candidates.length-1;

  latestBatch.unshift(
    candidates[i]
  );

  let cursor=
    candidates[i].timestamp;

  for (
    i=i-1;
    i>=0;
    i--
  ) {

    if (
      !cursor ||
      !candidates[i].timestamp
    ) {
      break;
    }

    const gap=
      cursor
      - candidates[i].timestamp;

    if (
      gap >
      30 * 60 * 1000
    ) {
      break;
    }

    latestBatch.unshift(
      candidates[i]
    );

    cursor=
      candidates[i].timestamp;
  }
}


// ========================================================
// Merge:
