}));

const contexts=$items('Attach Processing Context');
return items.map((item,index) => ({
  json:{
    ...contexts[index].json
  },
  binary:item.binary
}));

const contexts=$items('Attach Drive Download Context');
const store=$getWorkflowStaticData('global');

if (!store.users) {
  store.users={};
}

return items.map((item,index) => {
  const ctx=contexts[index].json;
  const filename=item.json?.data?.file;

  if (!filename) {
    throw new Error(
      'DRIVE_MATERIAL_UPLOAD_FILE_NOT_RETURNED: ' +
      JSON.stringify(item.json)
    );
  }

  const userKey=String(ctx.telegram_id);
  if (!store.users[userKey]) {
    throw new Error('DRIVE_MATERIAL_USER_NOT_FOUND');
  }

  const user=store.users[userKey];
  if (!Array.isArray(user.pending_flow_materials)) {
    user.pending_flow_materials=[];
  }

  const sceneId=Number(ctx.scene_id || 0);
  const duplicate=user.pending_flow_materials.some(existing =>
    String(existing.source_drive_file_id || '') === String(ctx.drive_file_id) ||
    (
      String(existing.url || '') === String(filename) &&
      Number(existing.scene_id || 0) === sceneId
    )
  );

  if (!duplicate) {
    user.pending_flow_materials.push({
      provider:'local',
      source:'flow',
      scene_id:sceneId,
      url:filename,
      duration:0,
      source_drive_file_id:String(ctx.drive_file_id),
      source_drive_name:String(ctx.drive_file_name || '')
    });
  }

  user.awaiting='flow_material_done';

  return {
    json:{
      ...ctx,
      uploaded_material:filename,
      was_duplicate:duplicate,
      flow_materials_count:user.pending_flow_materials.length
    }
  };
});

const contexts=$items('Save Drive Flow Material');
return items.map((item,index) => ({
  json:{
    ...contexts[index].json,
    drive_used_response:item.json
  }
}));

const input=$input.all();

if (!input.length) {
  return [];
}

const first=input[0].json;
const imported=input.filter(item => !item.json.was_duplicate);
const duplicates=input.filter(item => item.json.was_duplicate);
const lines=input.map(item =>
  `scene-${String(item.json.scene_id).padStart(3,'0')}  ${item.json.drive_file_name}`
);

return [{
  json:{
    chat_id:first.chat_id,
    telegram_id:first.telegram_id,
    reply:
`☁️ تم فحص Google Drive.

DRIVE_LIST: ${input.length}
FLOW_MATERIAL_CREATED: ${imported.length}
DUPLICATE_PREVENTION: ${duplicates.length}

${lines.join('\n')}`
  }
}];
